// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate, uint8 _decimals, uint128 _virtualBase, uint128 _virtualNft, uint56 _changeFee, bool _useStolenNftOracle, bool _payRoyalties) public {
        _feeRate = uint16(bound(_feeRate, 5001, type(uint16).max));
        _decimals = uint8(bound(_decimals, 0, 36));
        address baseToken = makeAddr("baseToken");
        address nftAddr = makeAddr("nft");
        MockERC20 mockBase = new MockERC20(_decimals);
        bool ok;
        try c.initialize(
            address(mockBase),
            nftAddr,
            _virtualBase,
            _virtualNft,
            _changeFee,
            _feeRate,
            bytes32(0),
            _useStolenNftOracle,
            _payRoyalties
        ) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "Initialization should revert for feeRate > 5000");
    }
}

contract MockERC20 {
    uint8 public decimals;
    constructor(uint8 _decimals) {
        decimals = _decimals;
    }
}
